    .map((p) => people.data?.find((q) => q.id === p.patronId))
    .filter((p): p is Person => p !== undefined);
  const shares = equalShares(mine.length);
  const names = mine
    .map((p, i) => ({ name: p.name, share: shares[i] }))
    .sort((a, b) => a.name.localeCompare(b.name))
    .map((p) => `${p.name} ${p.share}`);
